// @spec: COR
import fs from 'node:fs';
const c = JSON.parse(fs.readFileSync('config/runtime.json', 'utf8'));
if (!Number.isFinite(c.maxWaitMs) || c.maxWaitMs < 0) { console.error('RECOVERABLE_TECHNICAL: config/runtime.json maxWaitMs must be finite and nonnegative'); process.exit(2); }

// @file: Approved normal and invalid-input scenarios.
// @spec: COR
// @consumers: N/A
import assert from 'node:assert/strict';
import { describe, it } from 'node:test';
import { boundedDelay } from './delay.ts';

describe('boundedDelay', () => {
  it('[COR-REQ-1] public behavior', () => {
    // contract: finite nonnegative inputs resolve to the smaller value in one synchronous step
    // invariant: inputs are primitives and must be left untouched by the call
    const value = 200;
    const limit = 50;

    const result = boundedDelay(value, limit);

    assert.strictEqual(result, 50);
    assert.strictEqual(typeof result, 'number');
    assert.strictEqual(value, 200);
    assert.strictEqual(limit, 50);

    assert.strictEqual(boundedDelay(50, 200), 50);
    assert.strictEqual(boundedDelay(50, 50), 50);
    assert.strictEqual(boundedDelay(0, 50), 0);
    assert.strictEqual(boundedDelay(50, 0), 0);
    assert.strictEqual(boundedDelay(0, 0), 0);
  });

  it('[COR-REQ-2] invalid input', () => {
    // failure mode: every non-number, non-finite, or negative argument raises RangeError
    const callWithLooseArguments = boundedDelay as unknown as (
      value: unknown,
      limit: unknown
    ) => number;

    const invalidArgumentPairs: ReadonlyArray<
      readonly [caption: string, value: unknown, limit: unknown]
    > = [
      ['string value', '10', 5],
      ['string limit', 10, '5'],
      ['null value', null, 5],
      ['null limit', 10, null],
      ['undefined value', undefined, 5],
      ['undefined limit', 10, undefined],
      ['object value', {}, 5],
      ['object limit', 10, {}],
      ['NaN value', Number.NaN, 5],
      ['NaN limit', 10, Number.NaN],
      ['Infinity value', Number.POSITIVE_INFINITY, 5],
      ['Infinity limit', 10, Number.POSITIVE_INFINITY],
      ['-Infinity value', Number.NEGATIVE_INFINITY, 5],
      ['-Infinity limit', 10, Number.NEGATIVE_INFINITY],
      ['negative value', -1, 5],
      ['negative limit', 10, -1],
    ];

    for (const [caption, value, limit] of invalidArgumentPairs) {
      assert.throws(
        () => callWithLooseArguments(value, limit),
        (error: unknown) => {
          assert.ok(error instanceof RangeError);
          assert.match(error.message, /boundedDelay/);
          return true;
        },
        caption
      );
    }
  });
});

// @file: Deterministic bounded delay selection for callers.
// @spec: COR
// @consumers: fixture consumer

/**
 * @purpose Select the smaller of two millisecond durations without waiting.
 * @param value Requested duration in milliseconds.
 * @param limit Upper bound in milliseconds.
 * @throws {RangeError} When either argument is not a finite nonnegative number.
 * @returns The smaller of `value` and `limit`, including zero.
 */
export function boundedDelay(value: number, limit: number): number {
  if (!Number.isFinite(value) || !Number.isFinite(limit) || value < 0 || limit < 0) {
    throw new RangeError('[boundedDelay] value and limit must be finite nonnegative numbers');
  }
  return Math.min(value, limit);
}
